Object.assign(SNIP,{"l44s": "auto a = make_shared<int>(9);     // use_count = 1\nshared_ptr<int> b = a;            // chép: cùng giữ một vùng nhớ, use_count = 2\nb.reset();                        // b thôi giữ: use_count = 1\n// a hết phạm vi: use_count = 0, vùng nhớ được trả\n\nweak_ptr<int> w = a;              // trỏ tới nhưng KHÔNG giữ: use_count không tăng\nshared_ptr<int> t = w.lock();     // lấy lại một shared_ptr (rỗng nếu đã bị trả)\nif (w.expired()) cout << \"da bi tra\";", "l44u": "#include <memory>\nunique_ptr<int> p = make_unique<int>(5);      // cấp một int = 5 trên heap, p là chủ duy nhất\nauto s = make_unique<Sach>(\"Dac Nhan Tam\");    // gọi hàm tạo Sach(...)\ncout << *p;  s->doc();                         // dùng như con trỏ thường\nunique_ptr<int> q = move(p);                   // chuyển quyền: q giữ, p thành rỗng (nullptr)\nif (p == nullptr) cout << \"p rong\";\np.reset();          // trả vùng nhớ ngay (nếu đang giữ)\nint* tho = q.get(); // con trỏ thường để đọc nhờ, KHÔNG delete nó"});PRESET_NOTES["l44"]={"Ví dụ: unique_ptr tự trả vùng nhớ": "Không có dòng delete nào. Sach “Toan” bị hủy ngay ở dấu } của khối, vì s (unique_ptr) hết phạm vi. Vùng nhớ của p được trả khi main kết thúc. Xem cột Heap: hai khối lần lượt “đã tự giải phóng”.", "Ví dụ: chuyển quyền sở hữu bằng move": "taoSach trả unique_ptr ra ngoài (tự chuyển, không chép). move(a) chuyển sách sang b, a thành nullptr. docXong(move(b)) đưa luôn quyền sở hữu vào tham số s, nên sách bị hủy ở cuối docXong, trước “Cuoi main”.", "Lỗi: chép unique_ptr": "Truyền theo giá trị là chép, mà unique_ptr không chép được. Hàm chỉ cần đọc nên sửa thành void inGiaTri(const unique_ptr<int>& p), hoặc nhận int x và gọi inGiaTri(*p). Nếu thật sự muốn giao quyền: inGiaTri(move(p)).", "Lỗi: dùng unique_ptr đã move": "Sau move, p là nullptr: *p truy cập địa chỉ 0 và chương trình dừng (Segmentation fault). Sau khi move một biến, đừng dùng nó nữa trừ khi gán giá trị mới.", "Ví dụ: vector<unique_ptr> và đa hình": "make_unique<Vuong> tự đổi thành unique_ptr<Hinh>. Gọi h->dienTich() tra vtable như con trỏ thường. Cuối main, vector hủy từng phần tử; nhờ virtual ~Hinh(), hàm hủy của lớp con chạy trước (~Vuong rồi ~Hinh).", "Ví dụ: shared_ptr và use_count": "Chép a vào b: hai shared_ptr cùng một khối, use_count = 2 (sửa *b thì *a cũng thấy 10). Truyền theo giá trị vào xem là thêm một bản chép (3). Ra khỏi khối, b bị hủy: còn 1. reset(): về 0, khối được trả ngay.", "Lỗi: vòng tham chiếu shared_ptr": "Mỗi người được giữ bởi một biến của main và bởi người kia: use_count = 2. Cuối main, hai biến bị hủy, mỗi bên còn 1 và không bao giờ về 0: không có dòng “Huy” nào, cả hai khối bị rò rỉ (phần Kết quả báo vòng tham chiếu).", "Ví dụ: weak_ptr phá vòng": "weak_ptr không làm tăng use_count (vẫn là 1 1). lock() tạm lấy một shared_ptr để dùng. Hết khối, binh về 0 và bị hủy ngay; weak_ptr của An biết điều đó (expired). Cuối main An cũng bị hủy: không rò rỉ.", "Ví dụ: unique_ptr làm thành viên (quy tắc không)": "Xe không viết hàm hủy nào, nhưng khi x bị hủy, thành viên dc (unique_ptr) bị hủy theo và trả động cơ. Đó là quy tắc không ở Bài 43: thành viên tự quản lý thì lớp không cần tự viết hàm hủy, hàm chép."};EX_HINTS["l44"]=[["make_unique<Vuong>(a) trả về unique_ptr<Vuong>, tự đổi được thành unique_ptr<Hinh> khi push_back.", "Dùng ds[i]->dienTich() như con trỏ thường."], ["unique_ptr<Hang> x = kho.back(); là chép: lỗi biên dịch. Phải move(kho.back()).", "x được khai báo trong khối else, nên hàng bị hủy ở cuối khối đó, ngay sau dòng “Lay ...”."], ["use_count() đếm cả biến sach của thư viện, nên số người giữ là use_count() − 1.", "Gán giu[k] = sach khi giu[k] đã giữ chính cuốn đó thì use_count không đổi (thôi giữ bản cũ, giữ bản mới)."]];
/* ===================== BÀI 44 · unique_ptr, shared_ptr ===================== */
/* Bài 44 · unique_ptr, shared_ptr
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const P44=[{label:"Ví dụ: unique_ptr tự trả vùng nhớ",input:"",code:"#include <iostream>\n#include <memory>\n#include <string>\nusing namespace std;\n\nclass Sach {\n    string ten;\npublic:\n    Sach(string t) : ten(t) { cout << \"Tao \" << ten << \"\\n\"; }\n    ~Sach() { cout << \"Huy \" << ten << \"\\n\"; }\n    void doc() { cout << \"Doc \" << ten << \"\\n\"; }\n};\nint main() {\n    unique_ptr<int> p = make_unique<int>(5);\n    *p += 10;\n    cout << *p << \"\\n\";\n    {\n        auto s = make_unique<Sach>(\"Toan\");\n        s->doc();\n    }\n    cout << \"Sau khoi\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: chuyển quyền sở hữu bằng move",input:"",code:"#include <iostream>\n#include <memory>\n#include <string>\nusing namespace std;\n\nclass Sach {\n    string ten;\npublic:\n    Sach(string t) : ten(t) {}\n    ~Sach() { cout << \"Huy \" << ten << \"\\n\"; }\n    string layTen() const { return ten; }\n};\nunique_ptr<Sach> taoSach(string t) {\n    auto s = make_unique<Sach>(t);\n    return s;\n}\nvoid docXong(unique_ptr<Sach> s) {\n    cout << \"Doc xong \" << s->layTen() << \"\\n\";\n}\nint main() {\n    unique_ptr<Sach> a = taoSach(\"Ly\");\n    unique_ptr<Sach> b = move(a);\n    if (a == nullptr) cout << \"a rong, b giu \" << b->layTen() << \"\\n\";\n    docXong(move(b));\n    cout << \"Cuoi main\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Lỗi: chép unique_ptr",input:"",code:"#include <iostream>\n#include <memory>\nusing namespace std;\n\nvoid inGiaTri(unique_ptr<int> p) {\n    cout << *p << \"\\n\";\n}\nint main() {\n    unique_ptr<int> p = make_unique<int>(5);\n    inGiaTri(p);\n    return 0;\n}"},{label:"Lỗi: dùng unique_ptr đã move",input:"",code:"#include <iostream>\n#include <memory>\nusing namespace std;\n\nint main() {\n    unique_ptr<int> p = make_unique<int>(4);\n    unique_ptr<int> q = move(p);\n    cout << *q << \"\\n\";\n    cout << *p << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: vector<unique_ptr> và đa hình",input:"",code:"#include <iostream>\n#include <memory>\n#include <vector>\nusing namespace std;\n\nclass Hinh {\npublic:\n    virtual double dienTich() const = 0;\n    virtual ~Hinh() { cout << \"~Hinh\\n\"; }\n};\nclass Vuong : public Hinh {\n    double a;\npublic:\n    Vuong(double a) : a(a) {}\n    double dienTich() const override { return a * a; }\n    ~Vuong() { cout << \"~Vuong\\n\"; }\n};\nclass Tron : public Hinh {\n    double r;\npublic:\n    Tron(double r) : r(r) {}\n    double dienTich() const override { return 3.14 * r * r; }\n    ~Tron() { cout << \"~Tron\\n\"; }\n};\nint main() {\n    vector<unique_ptr<Hinh>> ds;\n    ds.push_back(make_unique<Vuong>(2));\n    ds.push_back(make_unique<Tron>(1));\n    for (const auto& h : ds) {\n        cout << h->dienTich() << \"\\n\";\n    }\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: shared_ptr và use_count",input:"",code:"#include <iostream>\n#include <memory>\nusing namespace std;\n\nvoid xem(shared_ptr<int> p) {\n    cout << \"Trong ham: \" << p.use_count() << \"\\n\";\n}\nint main() {\n    shared_ptr<int> a = make_shared<int>(9);\n    cout << a.use_count() << \"\\n\";\n    {\n        shared_ptr<int> b = a;\n        *b = 10;\n        cout << a.use_count() << \" \" << *a << \"\\n\";\n        xem(a);\n    }\n    cout << a.use_count() << \"\\n\";\n    a.reset();\n    cout << \"Da reset\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Lỗi: vòng tham chiếu shared_ptr",input:"",code:"#include <iostream>\n#include <memory>\n#include <string>\nusing namespace std;\n\nstruct Nguoi {\n    string ten;\n    shared_ptr<Nguoi> banThan;\n    Nguoi(string t) : ten(t) {}\n    ~Nguoi() { cout << \"Huy \" << ten << \"\\n\"; }\n};\nint main() {\n    auto an = make_shared<Nguoi>(\"An\");\n    auto binh = make_shared<Nguoi>(\"Binh\");\n    an->banThan = binh;\n    binh->banThan = an;\n    cout << an.use_count() << \" \" << binh.use_count() << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: weak_ptr phá vòng",input:"",code:"#include <iostream>\n#include <memory>\n#include <string>\nusing namespace std;\n\nstruct Nguoi {\n    string ten;\n    weak_ptr<Nguoi> banThan;\n    Nguoi(string t) : ten(t) {}\n    ~Nguoi() { cout << \"Huy \" << ten << \"\\n\"; }\n};\nint main() {\n    auto an = make_shared<Nguoi>(\"An\");\n    {\n        auto binh = make_shared<Nguoi>(\"Binh\");\n        an->banThan = binh;\n        binh->banThan = an;\n        cout << an.use_count() << \" \" << binh.use_count() << \"\\n\";\n        shared_ptr<Nguoi> b = an->banThan.lock();\n        if (b) cout << \"Ban cua An: \" << b->ten << \"\\n\";\n    }\n    if (an->banThan.expired()) cout << \"Binh da bi huy\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: unique_ptr làm thành viên (quy tắc không)",input:"",code:"#include <iostream>\n#include <memory>\n#include <string>\nusing namespace std;\n\nclass DongCo {\npublic:\n    DongCo() { cout << \"Lap dong co\\n\"; }\n    ~DongCo() { cout << \"Thao dong co\\n\"; }\n};\nclass Xe {\n    string ten;\n    unique_ptr<DongCo> dc;\npublic:\n    Xe(string t) : ten(t), dc(make_unique<DongCo>()) {\n        cout << \"Xe \" << ten << \" san sang\\n\";\n    }\n};\nint main() {\n    Xe x(\"A\");\n    cout << \"Chay\\n\";\n    return 0;\n}",viz:[{type:"mem"}]}];
const sim44=makeSim2(document.getElementById("sim-l44"),{id:"s44",presets:P44});
makeEx2(document.getElementById("ex-l44"),sim44,[{t:"Danh sách hình",d:"Nhập n rồi n hình: <code>V a<\/code> (hình vuông cạnh a) hoặc <code>C w h<\/code> (chữ nhật). Lưu chúng trong <code>vector&lt;unique_ptr&lt;Hinh&gt;&gt;<\/code> (lớp Hinh có hàm ảo thuần túy dienTich() và ten(), hàm hủy ảo), tạo bằng <code>make_unique<\/code>. In tổng diện tích, rồi dòng sau in tên và diện tích của hình lớn nhất (bằng nhau lấy hình đứng trước).",tests:[{in:"3\nV 3\nC 2 5\nV 4",out:"35\nVuong 16"},{in:"1\nC 3 7",out:"21\nChuNhat 21"},{in:"2\nC 2 2\nV 2",out:"8\nChuNhat 4"}],start:"#include <iostream>\n#include <memory>\n#include <vector>\n#include <string>\nusing namespace std;\n\nclass Hinh {\npublic:\n    virtual int dienTich() const = 0;\n    virtual string ten() const = 0;\n    virtual ~Hinh() {}\n};\n// class Vuong : public Hinh ...\n// class ChuNhat : public Hinh ...\nint main() {\n    int n;\n    cin >> n;\n    vector<unique_ptr<Hinh>> ds;\n    for (int i = 0; i < n; i++) {\n        char k;\n        cin >> k;\n        // ds.push_back(make_unique<...>(...));\n    }\n    return 0;\n}",need:/make_unique\s*</,needMsg:"Hãy tạo các hình bằng make_unique."},{t:"Lấy hàng ra khỏi kho",d:"Kho là <code>vector&lt;unique_ptr&lt;Hang&gt;&gt;<\/code>; lớp Hang có hàm hủy in <code>Huy ten<\/code>. Lệnh <code>them ten<\/code>: thêm hàng vào cuối kho. Lệnh <code>lay<\/code>: chuyển hàng cuối kho sang một biến unique_ptr cục bộ bằng <code>move<\/code>, bỏ ô cuối (<code>pop_back<\/code>), in <code>Lay ten<\/code> (kho rỗng thì in <code>Het hang<\/code>). Hàng lấy ra bị hủy khi biến cục bộ hết phạm vi. Cuối cùng in <code>Con k<\/code>; các hàng còn lại bị hủy khi kết thúc chương trình.",tests:[{in:"5\nthem a\nthem b\nlay\nthem c\nlay",out:"Lay b\nHuy b\nLay c\nHuy c\nCon 1\nHuy a"},{in:"2\nlay\nthem x",out:"Het hang\nCon 1\nHuy x"},{in:"3\nthem p\nthem q\nthem r",out:"Con 3\nHuy p\nHuy q\nHuy r"}],start:"#include <iostream>\n#include <memory>\n#include <vector>\n#include <string>\nusing namespace std;\n\nclass Hang {\n    string ten;\npublic:\n    Hang(string t) : ten(t) {}\n    ~Hang() { cout << \"Huy \" << ten << \"\\n\"; }\n    string layTen() const { return ten; }\n};\nint main() {\n    vector<unique_ptr<Hang>> kho;\n    int q;\n    cin >> q;\n    for (int i = 0; i < q; i++) {\n        string lenh;\n        cin >> lenh;\n        // them: kho.push_back(make_unique<Hang>(...));\n        // lay: unique_ptr<Hang> x = move(kho.back()); kho.pop_back(); ...\n    }\n    cout << \"Con \" << kho.size() << \"\\n\";\n    return 0;\n}",need:/move\s*\(\s*kho\.back\s*\(\s*\)\s*\)/,needMsg:"Hãy chuyển hàng ra bằng move(kho.back())."},{t:"Mượn sách",d:"Thư viện có một cuốn sách duy nhất, giữ bằng <code>shared_ptr&lt;int&gt; sach = make_shared&lt;int&gt;(mã)<\/code>. Có n người (đánh số 0…n−1), mỗi người giữ một <code>shared_ptr&lt;int&gt;<\/code> (ban đầu rỗng). Nhập n, mã sách, q rồi q lệnh: <code>muon i<\/code> (người i giữ sách; đang giữ rồi thì không đổi), <code>tra i<\/code> (người i thôi giữ), <code>dem<\/code> (in số người đang giữ, tính bằng <code>use_count()<\/code>). Cuối cùng in mã sách.",tests:[{in:"3 7 6\nmuon 0\nmuon 2\ndem\nmuon 2\ntra 0\ndem",out:"2\n1\n7"},{in:"1 42 3\ndem\ntra 0\ndem",out:"0\n0\n42"},{in:"2 5 4\nmuon 0\nmuon 1\ntra 1\ndem",out:"1\n5"}],start:"#include <iostream>\n#include <memory>\n#include <vector>\n#include <string>\nusing namespace std;\n\nint main() {\n    int n, ma, q;\n    cin >> n >> ma >> q;\n    shared_ptr<int> sach = make_shared<int>(ma);\n    vector<shared_ptr<int>> giu(n);\n    for (int i = 0; i < q; i++) {\n        string lenh;\n        cin >> lenh;\n        // muon: giu[k] = sach;   tra: giu[k].reset();   dem: dùng sach.use_count()\n    }\n    cout << *sach << \"\\n\";\n    return 0;\n}",need:/use_count\s*\(/,needMsg:"Hãy đếm bằng use_count()."}]);

makeQuiz("quiz44","score44",[{"q": "<code>unique_ptr&lt;int&gt; q = p;<\/code> (p là unique_ptr&lt;int&gt;) cho kết quả:", "o": ["q và p cùng giữ vùng nhớ", "Lỗi biên dịch: hàm chép của unique_ptr đã bị xóa", "p thành rỗng", "Lỗi khi chạy"], "a": 1, "e": "unique_ptr không chép được. Muốn chuyển quyền: unique_ptr<int> q = move(p);"}, {"q": "Sau <code>auto q = move(p);<\/code> với p là unique_ptr, p là:", "o": ["Vẫn giữ vùng nhớ cũ", "nullptr (rỗng)", "Một bản chép", "Đã bị hủy và không dùng được nữa (lỗi biên dịch nếu dùng)"], "a": 1, "e": "Quyền sở hữu đã sang q; p rỗng. Dùng *p lúc này là lỗi khi chạy (truy cập địa chỉ 0), không phải lỗi biên dịch."}, {"q": "<code>auto a = make_shared&lt;int&gt;(1); auto b = a; auto c = b; b.reset();<\/code> Khi đó <code>a.use_count()<\/code> là:", "o": ["1", "2", "3", "0"], "a": 1, "e": "a, b, c cùng giữ: 3; b.reset() bỏ một: còn 2 (a và c)."}, {"q": "Hai đối tượng giữ shared_ptr trỏ lẫn nhau. Cách sửa rò rỉ bộ nhớ là:", "o": ["Gọi delete bằng tay", "Đổi một chiều thành weak_ptr", "Đổi cả hai thành unique_ptr", "Tăng use_count"], "a": 1, "e": "weak_ptr không làm tăng use_count nên vòng bị phá; dùng lock() khi cần truy cập."}]);

